entries[237321] = { ["name"] = "Punkteleitfaden: Zähler starten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zeigt über Eurem Kopf einen Punktezähler an. Ihr beginnt mit 3 Punkten. Kann nur im Tiefschlag in Lorenhall verwendet werden.\nVerkaufspreis:" }
entries[237322] = { ["name"] = "Punkteleitfaden: Punkt entfernen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zieht Euch einen Trefferpunkt ab.\nVerkaufspreis:" }
entries[237323] = { ["name"] = "Punkteleitfaden: Punkt hinzufügen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Addiert einen Trefferpunkt für Euch.\nVerkaufspreis:" }
entries[237330] = { ["name"] = "Wegwerfhamburger", ["text"] = "Benutzen: Haltet einen Hamburger. (30 Sek. Abklingzeit)\n\"Anweisung: Sachte halten.\"\nVerkaufspreis:" }
entries[237331] = { ["name"] = "Wegwerfwürstchen", ["text"] = "Benutzen: Haltet ein Würstchen. (30 Sek. Abklingzeit)\n\"Warnung: Wird gesetzlich nicht als Nahrung anerkannt.\"\nVerkaufspreis:" }
entries[237332] = { ["name"] = "Einweggrill", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört einen Grill zum Kochen.\n\"Verwenden und dann ab in den Müll damit für maximale Bequemlichkeit.\"\nVerkaufspreis:" }
entries[237333] = { ["name"] = "Lorenhallkiste", ["text"] = "Benutzen: Haltet eine Goblinkiste. (30 Sek. Abklingzeit)\n\"Doppelt verstärkt. Nur zur Sicherheit.\"\nVerkaufspreis:" }
entries[237334] = { ["name"] = "Halb verzehrtes Mittagessen", ["text"] = "Benutzen: Haltet einen Essensbehälter. (30 Sek. Abklingzeit)\n\"Halb gegessen? Halber Preis!\"\nVerkaufspreis:" }
