entries[237342] = { ["name"] = "Sai der Renaissance", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Dolch\n1 Schaden Geschwindigkeit 1.80\n(0.6 Schaden pro Sekunde)\n\"Lasst Eure Wut und Euren Frust an Euren Feinden aus.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[237343] = { ["name"] = "Nunchaku der Renaissance", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Perfekt, um Gegner in der Luft zu jonglieren... oder Kuchen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
