entries[237345] = { ["name"] = "Streng limitierter Raketenschwimmer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ersetzt Euren Schwimmer 1 Stunde lang durch einen streng limitierten Raketenschwimmer.\n\nNur für echte Kenner! (15 Min Abklingzeit)\nVerkaufspreis:" }
