entries[237347] = { ["name"] = "Biologisch produzierter Wallensteinfiletschwimmer", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ersetzt Euren Schwimmer 1 Stunde durch biologisch produziertes Wallensteinfilet als Schwimmer.\n\nDie edelsten Fische beißen nur bei edelster Küche an! (15 Min Abklingzeit)\nVerkaufspreis:" }
