entries[237484] = { ["name"] = "Schrecken des Ödlands", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 19 beim Bund von K'aresh.\n\n\"Er ist nicht weltverschlingend böse, nur missverstanden.\"\nVerkäufer:\nOm'sirik\nZone:\nK'aresh\nKosten:\n11.375" }
entries[237485] = { ["name"] = "Schrecken der Nacht", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Lasst Euch nicht von seinen leuchtenden Farben täuschen. Er kann sich an wirklich alles und jeden anschleichen.\"\nErfolg:\nSelbstjustiz\nKategorie:\nWar Within" }
