entries[237746] = { ["name"] = "Kriegsschwerter der Valarjar", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigt Furorkrieger\n\"Helyas Verrat wird nie vergeben werden. Lasst sie unter den Wellen verrotten, fern der Hallen der Tapferkeit.\"" }
entries[237747] = { ["name"] = "Kriegsschwerter der Valarjar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n4 - 8 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+3 Stärke\n+4 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigt Furorkrieger\n\"Eigentlich ist es ihre Macht, die diese Waffen wahrhaft außergewöhnlich macht. Ihre Macht und ihr Hass treffen endlos auf Odyns Geist. Der Spannung zwischen diesen Energien durchdringt ewiglich diese Klingen...\"" }
entries[237748] = { ["name"] = "Schuppenstachel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigt Schutzkrieger\n\"Von hier entspringt die wahre Stärke. Aus tiefen Orten... in der Welt und in Euch selbst.\"" }
entries[237749] = { ["name"] = "Schuppe des Erdwächters", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n28 Rüstung\n+1 Stärke\n+4 Intelligenz\n+2 Ausdauer\nKlassen: Krieger\n80 ( 80)\nBenötigt Schutzkrieger\n\"Es war eine von Neltharions abgeworfenen Schuppen. Sie rettete Magnar das Leben. Der Strahl der Flamme teilte sich um die schwarze Schuppe, doch die Wucht selbst beförderte Magnar aus dem Hort und ließ ihn den Hang des Hochbergs hinunterrollen.\"" }
entries[237755] = { ["name"] = "Abhandlung über das Wissen des Rates", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Bei über 80% Gesundheit erhaltet Ihr 5% Hauptwert und Eure Verbündeten innerhalb von 20 Metern erhalten 25% Vermeidung.\n80 ( 80)\n\"Relikt der Kirin Tor\"" }
entries[237757] = { ["name"] = "Morastmoos", ["text"] = "Questgegenstand\n\"Feucht und schleimig. Wahrscheinlich mögen Schlangen es deshalb so gerne.\"" }
