entries[237762] = { ["name"] = "\"Harmloser\" XL-Scharfschützenentferner", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft eine erschütternde Bombe auf einen gegnerischen Spielercharakter in einer Entfernung zwischen 20 und 100 Metern und stößt alle Gegner an der Aufschlagstelle zurück.\n\nKann nur im Kriegsmodus in Lorenhall verwendet werden. (30 Sek. Abklingzeit)\n\"Effektiver als eine Handvoll Steine!\"\nVerkaufspreis:" }
entries[237771] = { ["name"] = "Skrogzahn", ["text"] = "Metaedelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Naga Wenn Ihr 8 Sek. lang keinen Schaden erleidet, erscheint eine Blase, die Euch abschirmt. Wenn sie platzt, fügt die Blase Gegnern in der Nähe Frostschaden zu, der gleichmäßig auf sie aufgeteilt wird.\n80 ( 80)\n\"Nagarelikt\"" }
entries[237774] = { ["name"] = "Megafon der Anrufung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört mehr durchtriebene Gegner in die Kuppel. (30 Sek. Abklingzeit)" }
