entries[238386] = { ["name"] = "Leerenberührtes Fragment", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, Euch ein Leerenfragment zu gewähren. Das Töten eines Gegners garantiert ein Leerenfragment. Wenn Ihr 15 Fragmente gesammelt habt, absorbiert Ihr deren Leerenenergie, was Eure Meisterschaft 10 Sek. lang um 9174 erhöht.\nVerkaufspreis:" }
entries[238390] = { ["name"] = "Siegel des Seelenbrechers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+2.508 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Schaden verursachenden Zauber und Fähigkeiten habe eine Chance, die Seele Eures Gegners zu splittern, was ( 203186 * 1 ) Schattenschaden im Verlauf von 10 Sek. verursacht. Wenn ein gesplitterter Gegner stirbt, absorbiert Ihr dessen verweilende Energie, was Eure Vielseitigkeit 10 Sek. lang um 1516 erhöht.\nVerkaufspreis:" }
entries[238391] = { ["name"] = "Behältnis des Ministers der Arathi", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+2.753 [Beweglichkeit oder Stärke oder Intelligenz]\n+ 1.256 Vielseitigkeit\nAnlegen: Ihr gehört zu den Ergebenen. Bis zu 5 Verbündete in bis zu 30 Metern Entfernung zu Euch erhalten alle 5 Sekunden 4729 Gesundheit.\nVerkaufspreis:" }
