entries[238726] = { ["name"] = "Drachenleckerli", ["text"] = "Benutzen: Stellt Aufladungen für Himmelsreiten vollständig wieder her und gewährt der Fluggeschwindigkeit einen Schub. Nur beim Himmelsreiten einsetzbar. (15 Sek. Abklingzeit)\n80 ( 80)" }
entries[238727] = { ["name"] = "Nostwins Gutschein", ["text"] = "Benutzen: Bringt Euch zum Ewigen Basar in der Nähe von Dalaran zurück. (15 Min Abklingzeit)\n80 ( 80)\n\"Beehrt uns bald wieder!\"" }
entries[238739] = { ["name"] = "Chronokorsar", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Chronokorsar oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Stets auf der Suche nach der nächsten goldenen Gelegenheit, ist dieser Pirat des ewigen Drachenschwarms durch die Zeitwege gesegelt, um eine Besatzung für den perfekten Beutezug zu finden.\"\nVerkäufer:\nJeder Zeitwanderungshändler\nKosten:\n5.000" }
entries[238740] = { ["name"] = "Destilliertes Wissen der Zeitwege", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nBenutzen: Erhöht die durch das Töten von Monstern und das Abschließen von Quests erhaltene Erfahrung um 5%.\n\nDer Abschluss eines Zeitwanderungsdungeons verstärkt den Effekt und setzt die Dauer zurück.\n\nBeim Erreichen von 4 Anwendungen erfolgt eine Umwandlung zu ' Meister der Zeitwege ', was den Effekt auf 30% erhöht." }
