entries[238897] = { ["name"] = "Frühlingsigel der Ernte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Das Frühlingsschwein der Ernte hat früh morgens am meisten Energie. Es verbringt den Großteil des Tages damit, nach Futter zu schnüffeln oder nach anderen Ernteschweinen zu rufen.\"\nHandelsposten" }
entries[238900] = { ["name"] = "Sommerigel der Ernte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Der Sommerigel der Ernte genießt es, einfach in der Sonne zu liegen oder in klarem Wasser zu schwimmen. Es zeigt hervorragende Leistungen bei der Nahrungssuche, doch es muss erst mal dazu überredet werden.\"\nHandelsposten" }
entries[238901] = { ["name"] = "Winterigel der Ernte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Der Winterigel der Ernte ist hauptsächlich nachtaktiv. Es ist etwas langsamer als andere Ernteigel, doch seine Ausdauer ist unübertroffen.\"\nHandelsposten" }
entries[238902] = { ["name"] = "Herbstigel der Ernte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Der Herbstigel der Ernte ist beim Erschnüffeln von Futter in kühleren Monaten nicht zu übertreffen. Sein ausgeprägter Geruchssinn macht es zu einem exzellenten Begleiter, wenn man in bewaldeten Gebieten auf Nahrungssuche geht, doch aromatischere Umgebungen könnten zum Problem werden.\"\nHandelsposten" }
entries[238903] = { ["name"] = "Umfunktionierte azerothische Kamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\"" }
entries[238904] = { ["name"] = "Animasauger", ["text"] = "Questgegenstand\nBenutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\nKann beim Zaubern laufen. (3 Sek. Abklingzeit)\n\"Anscheinend gibt es im hinteren Bereich ein Portal, das direkt nach K'aresh führt. Man hat Euch versichert, dass es sicher ist. Wahrscheinlich.\"" }
entries[238905] = { ["name"] = "Kondensationsscheibe", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Scheibe, um Kreaturen auf tragbare Größe zu schrumpfen.\n\"Kann geworfen werden, um Kreaturen auf eine tragbare Größe zu schrumpfen.\"" }
entries[238906] = { ["name"] = "Umfunktionierte azerothische Kamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\"" }
entries[238907] = { ["name"] = "Animakugel", ["text"] = "Questgegenstand\nBenutzen: Wirft Eurem freundlichen Tier einen Ball zu.\n\"Ein Animaball mit einer griffigen Oberfläche. Wenn Ihr ihn werft, quietscht er. Tiere scheinen ihn zu lieben.\"" }
entries[238908] = { ["name"] = "Umfunktionierte azerothische Kamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um die Flora und Fauna in der Nähe zu dokumentieren. (3 Sek. Abklingzeit)\n\"Hat die Initialen \"W.Z.\" auf der Rückseite. Wie Ve'nari darangekommen ist, ist ein Rätsel.\"" }
entries[238909] = { ["name"] = "Animasauger", ["text"] = "Questgegenstand\nBenutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\nKann beim Zaubern laufen. (3 Sek. Abklingzeit)\n\"Hat ein Portal auf der Rückseite der Waffe. Früher führte es nach K'aresh, aber wer weiß schon, wohin jetzt? Zumindest nicht hierher.\"" }
entries[238910] = { ["name"] = "Lasso", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Fängt einen ruhigen Nekrorochen mit dem Lasso, damit Ihr ihn für eine medizinische Untersuchung und Vitamine herbringen könnt. (6 Sek. Abklingzeit)\n\"Ein zu einem Lasso gebundenes Seil. Nichts Ausgefallenes.\"" }
entries[238911] = { ["name"] = "Pheromonzerstäuber", ["text"] = "Questgegenstand\nBenutzen: Sprüht einen penetranten Duft auf alles vor Euch. (3 Sek. Abklingzeit)\n\"Wird verwendet, um Pheromone auf die Kreaturen in der Oase zu sprühen. Nicht zur Anwendung am eigenen Körper.\"" }
entries[238912] = { ["name"] = "Einlullender Pfeil", ["text"] = "Questgegenstand\nBenutzen: Verschießt einen Betäubungspfeil auf Euer Ziel, der es in seligen Tiefschlaf versetzt.\n\"Betäubt alles, das er trifft, indem er vorübergehend das spirituelle Netz unterbricht. Nicht-invasiv und schmerzfrei. Offenbar ein üblicher Streich, den man ahnungslosen Freunden spielt.\"" }
entries[238913] = { ["name"] = "Kondensationsscheibe", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Scheibe, um Kreaturen auf tragbare Größe zu schrumpfen.\n\"Kann geworfen werden, um Kreaturen auf eine tragbare Größe zu schrumpfen.\"" }
entries[238914] = { ["name"] = "Hemets besänftigende Flöte", ["text"] = "Questgegenstand\nBenutzen: Besänftigt aufgebrachte Schlangen in der Oase in einem 30-Meter-Umkreis um Euch. (5 Sek. Abklingzeit)\n\"Die Schlangen sind unruhig. Ihr müsst sie mit Euren fantastischen Flötenkünsten besänftigen.\"" }
entries[238915] = { ["name"] = "Animakugel", ["text"] = "Questgegenstand\nBenutzen: Wirft Eurem freundlichen Tier einen Ball zu.\n\"Ein Animaball mit einer griffigen Oberfläche. Wenn Ihr ihn werft, quietscht er. Tiere scheinen ihn zu lieben.\"" }
entries[238916] = { ["name"] = "Animasauger", ["text"] = "Questgegenstand\nBenutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\nKann beim Zaubern laufen. (3 Sek. Abklingzeit)\n\"Hat ein Portal auf der Rückseite der Waffe. Früher führte es nach K'aresh, aber wer weiß schon, wohin jetzt? Zumindest nicht hierher.\"" }
entries[238920] = { ["name"] = "Dienstabzeichen der Strahlen der Flamme", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Zeichen der Dankbarkeit für den Kampf gegen die Sureki. Lässt sich bei Morgaens Tränen gegen Ausrüstung tauschen.\"" }
entries[238922] = { ["name"] = "Vorlage: Leerenkristallpanther", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man den Leerenkristallpanther herstellt.\nBenötigt Juwelierskunst von Khaz Algar\n(30)" }
entries[238924] = { ["name"] = "Leerengebundene Kugel der Geheimnisse", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nHandwerksmaterial\n\"Wird an Keech dem Großen gefunden.\"" }
