entries[238941] = { ["name"] = "Kaltflammenkernmäre", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine Kaltflammenkernmäre oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Im Krieg der Elementarlords wurden Kernmären oft als Lasttiere für die treuesten Leutnants der Feuerfürsten eingesetzt.\"\nHandelsposten" }
entries[238942] = { ["name"] = "Wietschi", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses anpassbare Haustier beschwört. Ihr könnt dieses Haustier an einer Tierpflegestation anpassen.\nMit Rechtsklick dieses anpassbare Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[238943] = { ["name"] = "Großer Rabe des Propheten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört den großen Raben des Propheten oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Als Prophet hat Medivh seine Schreiben in der Form eines schwarzen Raben überbracht. Auch wenn er nicht ganz so beeindruckend wie Gestaltwandeln ist, trägt dieser Vogel dennoch all das Ansehen seines Namensgebers.\"\nWoW-Shop" }
entries[238946] = { ["name"] = "Brief von Fasshaxe", ["text"] = "\"Euer Anteil an der Beute\"\n<Zum Lesen rechtsklicken>" }
entries[238947] = { ["name"] = "Arkanosteingroßhelm", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Besonders stark, wird allerdings gerade so von arkaner Magie zusammengehalten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
