entries[238966] = { ["name"] = "Kernmäre der Teufelsgeborenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine Kernmäre der Teufelsgeborenen oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Kernmären waren eine frühe Spezies auf Azeroth, die von den Elementarlords beansprucht wurde.\"\nPromotion" }
entries[238967] = { ["name"] = "Geschmolzene Kernmäre", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine geschmolzenen Kernmäre oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"In den Anfangstagen von Azeroth beherrschten diese elementaren Raubtiere den vom Inferno geschwängerten Himmel von Ragnaros’ Reich.\"\nHandelsposten" }
entries[238968] = { ["name"] = "Kernmäre der Lavageborenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine Kernmäre der Lavageborenen oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Unter den Augen der Elementarlords wurden viele Kernmären von deren Kräften verderbt und zu treuen Reittieren und Partnern.\"\nHandelsposten" }
