entries[239004] = { ["name"] = "Säckchen des strahlenden Dienstes", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Gabe der höchstrangigen Mitglieder der Strahlen der Flamme für die erfolgreiche Abwehr der Truppen der Sureki. Enthält Resonanzkristalle und eine Marke, die bei Morgaens Tränen gegen Ausrüstung eingetauscht werden kann.\"\n<Zum Öffnen rechtsklicken>" }
