entries[239008] = { ["name"] = "Gamaschen des Mondkinds", ["text"] = "Wird beim Aufheben gebunden\nBeine Leder\n6 Rüstung\n+4 [Beweglichkeit oder Intelligenz]\n+6 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\n+ 4 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
