entries[239015] = { ["name"] = "Zuckerkieselpaket", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 15 Sek. ( 630000 / 5 * 15) Gesundheit wieder her. Wenn Ihr mindestens 15 Sek. mit Essen verbringt, spürt Ihr die Liebe und Eure Moral wird für 2 Stunden gestärkt.\nBenötigt Liebe liegt in der Luft\n\"Mit echten Kieseln hergestellt!\"" }
entries[239018] = { ["name"] = "Siegerpodest", ["text"] = "Spielzeug\nBenutzen: Platziert ein Siegerpodest und gebt an! (20 Min Abklingzeit)\nErfordert den Abschluss der Quest \"Woche 2: Wir kommen richtig in Fahrt\"." }
entries[239019] = { ["name"] = "Dreistbällchentasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Scharfes Dreistbällchen beschwören oder wieder freigeben.\n80 ( 80)\nErfordert den Abschluss der Quest \"Woche 3: Verbreitet die Kunde\"." }
entries[239020] = { ["name"] = "Leckerli der Terrorschildkröte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert den Abschluss der Quest \"Woche 4: Sie haben von Euch gehört\".\n\n\"Vinnie Naschkatze hielt diese seltene Albinoschildkröte geheim, bis es an der Zeit war, Durchtriebene Duos zu fördern.\"\nQuest:\nEine weitere hervorragende Woche!\nEreignis:\nDurchtriebene Duos" }
