entries[239074] = { ["name"] = "Leerenköder", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft den Leerenköder auf die Überreste eines besiegten Leerensturms an Laacunas Bruch, um Ramon'ta anzulocken. (6 Sek. Abklingzeit)\n\"Diese Kugeln können Leerenenergie enthalten und freigeben, wodurch sie je nach Bedarf als Köder oder Speicher genutzt werden können.\"" }
