entries[239076] = { ["name"] = "Herold von Sa'bak", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Tol'vir sprechen vom legendären Sa'bak, einem großen Krokilisken, der dem heiligen Tal des Kraters von Un'Goro entsprungen sein soll. Auch wenn nur wenige Sa'bak je mit eigenen Augen gesehen haben, glauben viele, dass er von den Titanenhütern gesegnet wurde, um die weitreichenden Wasserwege Uldums zu schützen.\"\nWoW-Shop" }
entries[239078] = { ["name"] = "Geringe Rune der unendlichen Sterne", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Verzaubert einen Helm mit der geringen Rune der unendlichen Sterne.\n\nEure Zauber und Fähigkeiten haben eine Chance, einen Gegner in der Nähe mit einem unendlichen Stern zu treffen, der ihm ( 1 * 211298) Arkanschaden zufügt und seinen durch Eure unendlichen Sterne erlittenen Schaden um ( 1 * 73954) erhöht. Bis zu 6-mal stapelbar, bevor der Effekt zurückgesetzt wird.\n\nKann nicht auf Gegenstände unter Stufe 350 angewandt werden. Dieser Effekt ist flüchtig und funktioniert nur in Saison 2 von The War Within.\nVerkaufspreis:" }
entries[239080] = { ["name"] = "Große Rune der unendlichen Sterne", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Verzaubert einen Helm mit der großen Rune der unendlichen Sterne.\n\nEure Zauber und Fähigkeiten haben eine Chance, einen Gegner in der Nähe mit einem unendlichen Stern zu treffen, der ihm ( 1 * 362226) Arkanschaden zufügt und seinen durch Eure unendlichen Sterne erlittenen Schaden um ( 1 * 126779) erhöht. Bis zu 6-mal stapelbar, bevor der Effekt zurückgesetzt wird.\n\nKann nicht auf Gegenstände unter Stufe 350 angewandt werden. Dieser Effekt ist flüchtig und funktioniert nur in Saison 2 von The War Within.\nVerkaufspreis:" }
