entries[239093] = { ["name"] = "Geringe Rune des Leerenrituals", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Verzaubert einen Helm mit der geringen Rune des Leerenrituals.\n\nGewährt 'Leerenritual', was Euren Zaubern und Fähigkeiten eine Chance verleiht, alle Sekundärwerte 20 Sek. lang pro Sekunde um 47 zu erhöhen.\n\nKann nicht auf Gegenstände unter Stufe 350 angewandt werden. Dieser Effekt ist flüchtig und funktioniert nur in Saison 2 von The War Within.\nVerkaufspreis:" }
entries[239095] = { ["name"] = "Große Rune des Leerenrituals", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Verzaubert einen Helm mit der großen Rune des Leerenrituals.\n\nGewährt 'Leerenritual', was Euren Zaubern und Fähigkeiten eine Chance verleiht, alle Sekundärwerte 20 Sek. lang pro Sekunde um 82 zu erhöhen.\n\nKann nicht auf Gegenstände unter Stufe 350 angewandt werden. Dieser Effekt ist flüchtig und funktioniert nur in Saison 2 von The War Within.\nVerkaufspreis:" }
entries[239098] = { ["name"] = "Nachbarschaftssatzung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Veröffentlicht die Nachbarschaftssatzung und ermöglicht Euch, andere Spieler um Unterschriften zu bitten. (10 Sek. Abklingzeit)\n\"Eine Satzung, um Eure eigene Nachbarschaft zu gründen.\"" }
entries[239105] = { ["name"] = "Ungewöhnliche Edelsteine", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nHandwerksmaterial\n\"Ein Paar Edelsteine, deren geschliffene Facetten Schlangenaugen nachempfunden sind. Kann in verstörenden Visionen gefunden werden.\"" }
entries[239106] = { ["name"] = "Schattenerfüllter Onyx", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (20)\nHandwerksmaterial\n\"Ein Edelstein ungewöhnlicher Färbung. Kann in verstörenden Visionen gefunden werden.\"" }
entries[239107] = { ["name"] = "Schwarzbluterfüllte Stange", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (4)\nHandwerksmaterial\n\"Sie sieht aus, als wäre sie lebendig. Kann in verstörenden Visionen gefunden werden.\"" }
