entries[239118] = { ["name"] = "Kiste des Gipfels", ["text"] = "Wird beim Aufheben gebunden\n\"Wöchentliche Truhe mit Materialien zur Aufwertung von Ausrüstung, Gold und vielem mehr.Die ersten beiden wöchentlichen Truhen, die Ihr Euch jede Woche verdient, enthalten einen Ausrüstungsgegenstand des Veteranen. Die ersten vier wöchentlichen Truhen, die Ihr Euch jede Woche verdient, enthalten einen restaurierten Kastenschlüssel.\"\n<Zum Öffnen rechtsklicken>" }
