entries[239146] = { ["name"] = "Vergoldete Verstärkungsmatrix", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nBenutzbar mit: Rezepte aus Khaz Algar für epische Ausrüstungsteile, die mit Funken des Glücks hergestellt werden.\n\"Ermächtigt hergestellte Gegenstände über ihre standardmäßigen Beschränkungen hinaus. Kann bei Llande in Dornogal erworben werden.\"\nVerkaufspreis:" }
entries[239153] = { ["name"] = "Schlüssel der ewigen Nacht", ["text"] = "Questgegenstand\n\"Dieses Gerät summt lautlos, seine Infraschallmelodie ist eher zu spüren als zu hören.\"" }
entries[239154] = { ["name"] = "Schlüssel des abnehmenden Mondes", ["text"] = "Questgegenstand\n\"Dieses Gerät fängt Umgebungslicht ein und reflektiert es in einem silbrigen Farbton.\"" }
entries[239155] = { ["name"] = "Schlüssel der dunklen Sonne", ["text"] = "Questgegenstand\n\"Dieses Gerät wird von innen durch etwas beleuchtet, was kein Licht ist. Das ist gleichzeitig widersprüchlich und unbestreitbar.\"" }
